fn bits8(v: i32) -> i32 {
    let mut n: i32 = 0;
    let mut x: i32 = v & 255;
    let mut i: i32 = 0;
    while i < 8 {
        n = n + (x & 1);
        x = x >> 1;
        i = i + 1;
    }
    n
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(2, 20260730);
    }
    if t % 2 == 0 {
        let seed: i32 = host::display::state_get(2) * 1103515245 + 12345;
        host::display::state_set(2, seed);
        let b: i32 = bits8(seed >> 12);
        let cnt: i32 = host::display::state_get(8 + b) + 1;
        host::display::state_set(8 + b, cnt);
        host::display::state_set(3, host::display::state_get(3) + 1);
        if cnt > 360 {
            let mut i: i32 = 0;
            while i < 9 {
                host::display::state_set(8 + i, host::display::state_get(8 + i) / 2);
                i = i + 1;
            }
            host::display::state_set(3, host::display::state_get(3) / 2);
        }
    }
    host::display::clear(0x0c0c0e);
    let bw: i32 = 44;
    let x0: i32 = (w - bw * 9) / 2;
    let base: i32 = h - 60;
    let mut i: i32 = 0;
    while i < 9 {
        let c: i32 = host::display::state_get(8 + i);
        let mut bh: i32 = c;
        if bh > 360 { bh = 360; }
        host::display::fill_rect(x0 + i * bw, base - bh, bw - 3, bh, 0x60a0d0);
        host::display::draw_number(x0 + i * bw + 14, base + 10, i, 0x808080, 1);
        i = i + 1;
    }
    host::display::draw_string(x0, 20, "HEADS IN 8 FLIPS", 0x808080, 1);
    host::display::draw_string(x0, 36, "BALLS", 0x606060, 1);
    host::display::draw_number(x0 + 60, 36, host::display::state_get(3), 0xffffff, 1);
    host::display::present();
}
